// The "selling" half of every service page: the client's problem, what is
// delivered, what it costs, how long it takes, and the questions people ask
// before they order. servicesData.js keeps the pipeline, titles and media;
// this file keeps the copy that changes with the offer.
//
// FIGURES ARE SAMPLES. Every price, turnaround and revision count below is a
// placeholder written to show the client the layout — they are plausible for
// the Swiss market but not the studio's actual rates. Replace them from
// the client's price list before launch; nothing else on the page depends
// on their exact values.
//
// Shape per slug:
//   intro / introDe            one paragraph under the "what it solves" title
//   problems[]                 { problem, title, desc } + De siblings
//   deliverables / deliverablesDe
//   investment                 { from, unit, unitDe, includes, includesDe,
//                                turnaround, turnaroundDe, revisions }
//   faq[]                      { q, a, qDe, aDe }
// web-development keeps intro/problems/deliverables in servicesData.js and
// only takes investment + faq from here.

import { mergeOverlay } from "@/lib/i18n";
import esOverlay from "@/data/es/serviceContent.json";

export const PRICE_CURRENCY = "CHF";

export const serviceContent = {
  "exterior-visualization": {
    intro: "A buyer cannot picture a facade from an elevation, and a municipal council will not approve a building it cannot see in its street. One photorealistic exterior view answers both: the project in its real surroundings, at the hour of day that flatters it, before the first excavator arrives.",
    introDe: "Ein Käufer kann sich eine Fassade nicht aus einer Ansicht vorstellen, und ein Gemeinderat genehmigt kein Gebäude, das er nicht in seiner Strasse sieht. Eine fotorealistische Aussenvisualisierung beantwortet beides: das Projekt in seiner echten Umgebung, zur Tageszeit, die es am besten zeigt, bevor der erste Bagger kommt.",
    problems: [
      { problem: "The brochure sells concrete per square metre", problemDe: "Die Broschüre verkauft Beton pro Quadratmeter", title: "A home a buyer can recognise", titleDe: "Ein Zuhause, das ein Käufer erkennt", desc: "Plans convince engineers. Buyers decide on the image of the building they would come home to: the balcony, the entrance, the light at six in the evening. We set the camera where a future resident would stand and build the mood around that moment.", descDe: "Pläne überzeugen Ingenieure. Käufer entscheiden am Bild des Hauses, in das sie heimkommen würden: Balkon, Eingang, Licht um sechs Uhr abends. Wir setzen die Kamera dorthin, wo ein künftiger Bewohner stünde, und bauen die Stimmung um diesen Moment." },
      { problem: "The site context is missing", problemDe: "Der Kontext des Grundstücks fehlt", title: "Built into the real street", titleDe: "In die echte Strasse gebaut", desc: "A rendering on a white ground proves nothing. We model the neighbours, the terrain and the existing trees from survey data and site photos, so the new volume sits exactly where it will stand — the image planning offices and councils trust.", descDe: "Ein Rendering auf weissem Grund beweist nichts. Wir modellieren Nachbarn, Gelände und Bestandsbäume aus Vermessungsdaten und Fotos, damit das neue Volumen genau dort steht, wo es gebaut wird — das Bild, dem Bauämter und Gemeinderäte vertrauen." },
      { problem: "Materials change during planning", problemDe: "Materialien ändern sich in der Planung", title: "One model, every variant", titleDe: "Ein Modell, jede Variante", desc: "Timber or render, dark or light window frames: once the scene exists, a material study is a matter of hours, not a new commission. The same model later feeds the bird's-eye view, the animation and the 360° tour.", descDe: "Holz oder Putz, dunkle oder helle Fensterrahmen: Steht die Szene, ist eine Materialstudie eine Sache von Stunden, kein neuer Auftrag. Dasselbe Modell speist später die Vogelperspektive, die Animation und den 360°-Rundgang." }
    ],
    deliverables: ["Photorealistic exterior views at 4K or larger, print- and web-ready", "Camera and mood proposals as grey renders before the final", "Real surroundings from your survey, site photos or satellite data", "Two rounds of revisions on the final image", "Layered files on request for your graphic team"],
    deliverablesDe: ["Fotorealistische Aussenansichten in 4K oder grösser, für Print und Web", "Kamera- und Stimmungsvorschläge als Grau-Renderings vor dem Final", "Echte Umgebung aus Ihrer Vermessung, Fotos oder Satellitendaten", "Zwei Korrekturrunden am finalen Bild", "Auf Wunsch Ebenen-Dateien für Ihr Grafikteam"],
    investment: { from: 690, unit: "per view", unitDe: "pro Ansicht", includes: ["Scene setup from your plans or model", "Grey camera study for approval", "Two revision rounds", "4K delivery for print and web"], includesDe: ["Szenenaufbau aus Ihren Plänen oder Ihrem Modell", "Grau-Kamerastudie zur Freigabe", "Zwei Korrekturrunden", "Lieferung in 4K für Print und Web"], turnaround: "5–7 working days for the first view, 2–3 days for each further view from the same model", turnaroundDe: "5–7 Arbeitstage für die erste Ansicht, 2–3 Tage für jede weitere aus demselben Modell", revisions: 2 },
    faq: [
      { q: "What do you need to start an exterior visualisation?", qDe: "Was brauchen Sie für eine Aussenvisualisierung?", a: "Plans as DWG or PDF (site plan, floor plans, elevations, sections), a materials list or reference photos, and anything you have on the surroundings — survey, site photos, drone shots. A 3D model (SketchUp, Revit, ArchiCAD, IFC) shortens the first stage; it is not required.", aDe: "Pläne als DWG oder PDF (Situationsplan, Grundrisse, Fassaden, Schnitte), eine Materialliste oder Referenzfotos und alles zur Umgebung — Vermessung, Fotos vom Grundstück, Drohnenaufnahmen. Ein 3D-Modell (SketchUp, Revit, ArchiCAD, IFC) verkürzt die erste Phase, ist aber nicht nötig." },
      { q: "How long does an exterior rendering take?", qDe: "Wie lange dauert ein Aussenrendering?", a: "Five to seven working days from complete documents to the final image: grey camera study on day two, coloured preview around day four, final after your feedback. Further views from the same model take two to three days each.", aDe: "Fünf bis sieben Arbeitstage ab vollständigen Unterlagen bis zum finalen Bild: Grau-Kamerastudie am zweiten Tag, farbige Vorschau um den vierten Tag, Final nach Ihrem Feedback. Weitere Ansichten aus demselben Modell dauern je zwei bis drei Tage." },
      { q: "How many revision rounds does an exterior rendering include?", qDe: "Wie viele Korrekturrunden sind bei einer Aussenvisualisierung inbegriffen?", a: "Two on the final image, plus the camera and mood approval before it. Changes to the architecture itself after approval are quoted separately, because they mean rebuilding the model.", aDe: "Zwei am finalen Bild, dazu die Freigabe von Kamera und Stimmung davor. Änderungen an der Architektur selbst nach der Freigabe werden separat offeriert, weil sie einen Umbau des Modells bedeuten." },
      { q: "Can an exterior visualisation be montaged into a site photo?", qDe: "Kann eine Aussenvisualisierung in ein Foto des Grundstücks montiert werden?", a: "Yes. Photomontage into a real photograph is often the right choice for building permits: the surroundings are provably real. We match perspective, lens and light to the photo and insert the building.", aDe: "Ja. Eine Fotomontage in eine echte Aufnahme ist für Baugesuche oft die richtige Wahl: Die Umgebung ist nachweislich echt. Wir gleichen Perspektive, Brennweite und Licht an das Foto an und setzen das Gebäude ein." },
      { q: "In which formats are exterior renderings delivered?", qDe: "In welchen Formaten werden Aussenrenderings geliefert?", a: "JPEG and PNG at 4K or the size you need for print, sRGB for web and CMYK on request. Layered PSD files for your graphic team are available for a small surcharge.", aDe: "JPEG und PNG in 4K oder in der Grösse, die Sie für den Druck brauchen, sRGB für Web und CMYK auf Wunsch. Ebenen-PSDs für Ihr Grafikteam gibt es gegen einen kleinen Aufpreis." },
      { q: "Do you work directly with our architect on the exterior visualisation?", qDe: "Arbeiten Sie bei der Aussenvisualisierung direkt mit unserem Architekten?", a: "Usually, yes. Questions about details, materials and dimensions go straight to the office; you receive the previews and give the final approval. It saves a round of forwarding on every question.", aDe: "In der Regel ja. Fragen zu Details, Materialien und Massen gehen direkt ans Büro; Sie erhalten die Vorschauen und geben die finale Freigabe. Das spart bei jeder Frage eine Weiterleitung." }
    ]
  },

  "interior-visualization": {
    intro: "An empty floor plan is a rectangle with a number. An interior rendering is the evening a buyer imagines in it: the kitchen island, the oak floor, the view from the sofa. For a show apartment that will not exist for two years, it is the show apartment.",
    introDe: "Ein leerer Grundriss ist ein Rechteck mit einer Zahl. Eine Innenvisualisierung ist der Abend, den sich ein Käufer darin vorstellt: die Kücheninsel, der Eichenboden, der Blick vom Sofa. Für eine Musterwohnung, die es erst in zwei Jahren gibt, ist sie die Musterwohnung.",
    problems: [
      { problem: "Buyers cannot read floor plans", problemDe: "Käufer können Grundrisse nicht lesen", title: "Rooms with a sense of scale", titleDe: "Räume mit Gefühl für die Grösse", desc: "Eye-level cameras, real furniture dimensions and daylight from the actual window orientation. A buyer sees that the dining table fits, that the morning sun reaches the kitchen, that the bedroom is quiet at the back.", descDe: "Kameras auf Augenhöhe, echte Möbelmasse und Tageslicht aus der tatsächlichen Fensterorientierung. Ein Käufer sieht, dass der Esstisch Platz hat, dass die Morgensonne die Küche erreicht, dass das Schlafzimmer hinten ruhig liegt." },
      { problem: "The standard finish looks like every other project", problemDe: "Der Standardausbau sieht aus wie jedes andere Projekt", title: "Your materials, styled for your buyer", titleDe: "Ihre Materialien, inszeniert für Ihren Käufer", desc: "We build the interior from your finish schedule — the actual parquet, the actual kitchen fronts — and furnish it for the people who will buy: a young family in Winterthur is not a retired couple in Zug. The furniture is a sales argument, not decoration.", descDe: "Wir bauen den Innenraum aus Ihrer Ausbauliste — das echte Parkett, die echten Küchenfronten — und richten ihn für die Menschen ein, die kaufen werden: Eine junge Familie in Winterthur ist kein Rentnerpaar in Zug. Die Möblierung ist ein Verkaufsargument, keine Dekoration." },
      { problem: "Every unit type needs its own image", problemDe: "Jeder Wohnungstyp braucht sein eigenes Bild", title: "A series, not a single picture", titleDe: "Eine Serie, kein Einzelbild", desc: "Living room, kitchen, bathroom and the master bedroom of each type, in one consistent light and style, so the brochure and the project website read as one project. Additional views from a finished scene cost a fraction of the first.", descDe: "Wohnzimmer, Küche, Bad und Elternschlafzimmer jedes Typs, in einem durchgehenden Licht und Stil, damit Broschüre und Projektwebsite als ein Projekt lesen. Weitere Ansichten aus einer fertigen Szene kosten einen Bruchteil der ersten." }
    ],
    deliverables: ["Photorealistic interior views at 4K, print- and web-ready", "Furnishing and styling matched to your target buyer", "Materials from your finish schedule, with alternatives on request", "Two rounds of revisions on the final image", "Matching 360° panoramas from the same scene, if you need a tour"],
    deliverablesDe: ["Fotorealistische Innenansichten in 4K, für Print und Web", "Möblierung und Styling passend zu Ihrer Zielgruppe", "Materialien aus Ihrer Ausbauliste, auf Wunsch mit Alternativen", "Zwei Korrekturrunden am finalen Bild", "Passende 360°-Panoramen aus derselben Szene, falls Sie einen Rundgang brauchen"],
    investment: { from: 590, unit: "per view", unitDe: "pro Ansicht", includes: ["Scene from your plans and finish schedule", "Furnishing and styling", "Two revision rounds", "4K delivery for print and web"], includesDe: ["Szene aus Ihren Plänen und Ihrer Ausbauliste", "Möblierung und Styling", "Zwei Korrekturrunden", "Lieferung in 4K für Print und Web"], turnaround: "5–7 working days for the first view, 2–3 days for each further view in the same apartment", turnaroundDe: "5–7 Arbeitstage für die erste Ansicht, 2–3 Tage für jede weitere in derselben Wohnung", revisions: 2 },
    faq: [
      { q: "What do you need for an interior visualisation?", qDe: "Was brauchen Sie für eine Innenvisualisierung?", a: "Floor plans with the window positions, the finish schedule (floors, kitchen, bathroom tiles, doors) and a few words about who the buyer is. Reference images of interiors you like help us hit the style in the first preview.", aDe: "Grundrisse mit den Fensterpositionen, die Ausbauliste (Böden, Küche, Badplatten, Türen) und ein paar Worte dazu, wer der Käufer ist. Referenzbilder von Innenräumen, die Ihnen gefallen, helfen, den Stil schon in der ersten Vorschau zu treffen." },
      { q: "Can the interior rendering show the real kitchen and bathroom products?", qDe: "Kann das Innenrendering die echten Küchen- und Badprodukte zeigen?", a: "Yes. If the supplier provides 3D data or product photos, we model the specified fronts, fittings and sanitary ware, so the rendering is also a reliable preview for the buyer's finish selection.", aDe: "Ja. Stellt der Lieferant 3D-Daten oder Produktfotos bereit, modellieren wir die ausgeschriebenen Fronten, Armaturen und Sanitärobjekte — das Rendering ist dann auch eine verlässliche Vorschau für die Bemusterung." },
      { q: "How long does an interior rendering take?", qDe: "Wie lange dauert eine Innenvisualisierung?", a: "Five to seven working days for the first view of an apartment, including the grey layout preview and one coloured preview. Each further view from the same scene takes two to three days.", aDe: "Fünf bis sieben Arbeitstage für die erste Ansicht einer Wohnung, inklusive Grau-Vorschau und einer farbigen Vorschau. Jede weitere Ansicht aus derselben Szene dauert zwei bis drei Tage." },
      { q: "Can an interior visualisation be delivered in day and evening light?", qDe: "Gibt es die Innenvisualisierung in Tages- und Abendlicht?", a: "A second lighting mood from an approved scene — evening, dusk, overcast — is an option at a reduced rate, because the scene already exists.", aDe: "Eine zweite Lichtstimmung aus einer freigegebenen Szene — Abend, Dämmerung, bedeckt — ist eine Option zum reduzierten Preis, weil die Szene bereits steht." },
      { q: "How realistic are interior renderings?", qDe: "Wie realistisch sind Innenrenderings?", a: "Photorealistic. Our interiors are used in sales documentation, on project websites and in listings. Where a detail is still undecided, we say so and show the standard variant rather than inventing one.", aDe: "Fotorealistisch. Unsere Innenraumbilder werden in Verkaufsdokumentationen, auf Projektwebsites und in Inseraten eingesetzt. Wo ein Detail noch offen ist, sagen wir das und zeigen die Standardvariante, statt eine zu erfinden." },
      { q: "Can the interior visualisation become a 360° tour?", qDe: "Kann aus der Innenvisualisierung ein 360°-Rundgang werden?", a: "Yes, and it is the most economical way to get one: the panoramas are rendered from the scene that already exists, so a five-room tour costs a fraction of building it separately.", aDe: "Ja, und das ist der günstigste Weg dorthin: Die Panoramen werden aus der bereits bestehenden Szene gerendert, ein Rundgang mit fünf Räumen kostet so einen Bruchteil eines separaten Aufbaus." }
    ]
  },

  "animation-mood-film": {
    intro: "A still image shows a building. A film shows a morning there: the light moving across the facade, someone opening the balcony door, the street waking up. For a project launch, a sales event or a social campaign, sixty seconds of that do what no brochure can.",
    introDe: "Ein Standbild zeigt ein Gebäude. Ein Film zeigt einen Morgen dort: das Licht, das über die Fassade wandert, jemand, der die Balkontür öffnet, die Strasse, die aufwacht. Für einen Projektstart, einen Verkaufsanlass oder eine Social-Media-Kampagne tun sechzig Sekunden davon, was keine Broschüre kann.",
    problems: [
      { problem: "The launch needs attention, not information", problemDe: "Der Start braucht Aufmerksamkeit, nicht Information", title: "A story in sixty seconds", titleDe: "Eine Geschichte in sechzig Sekunden", desc: "We write a short storyboard first — arrival, the facade, the living room, the view — and agree the mood and music before a frame is rendered. The film is cut for where it will play: the website hero, a sales event screen, a 15-second vertical for Instagram.", descDe: "Wir schreiben zuerst ein kurzes Storyboard — Ankunft, Fassade, Wohnzimmer, Aussicht — und einigen uns auf Stimmung und Musik, bevor ein Frame gerendert wird. Der Film wird für den Ort geschnitten, an dem er läuft: Website-Hero, Bildschirm am Verkaufsanlass, 15 Sekunden vertikal für Instagram." },
      { problem: "Renderings already exist, but nothing moves", problemDe: "Renderings gibt es schon, aber nichts bewegt sich", title: "Motion from your existing scenes", titleDe: "Bewegung aus Ihren bestehenden Szenen", desc: "If we built your stills, the scenes are ready and the film starts at the camera path. If another studio did, we can animate their delivered images with parallax, light and moving people — the economical way to a hero video.", descDe: "Haben wir Ihre Standbilder gebaut, stehen die Szenen und der Film beginnt beim Kamerapfad. Stammen sie von einem anderen Studio, animieren wir die gelieferten Bilder mit Parallaxe, Licht und bewegten Menschen — der günstige Weg zu einem Hero-Video." },
      { problem: "Investors want to see the whole thing", problemDe: "Investoren wollen das Ganze sehen", title: "From the quarter to the kitchen", titleDe: "Vom Quartier bis in die Küche", desc: "One continuous flight from the aerial context into the apartment tells an investor what twenty slides cannot: how the project sits in its town, how the units connect to the courtyard, what the standard looks like inside.", descDe: "Ein durchgehender Flug vom Luftbild bis in die Wohnung erzählt einem Investor, was zwanzig Folien nicht können: wie das Projekt in seiner Stadt liegt, wie die Wohnungen an den Hof anschliessen, wie der Standard innen aussieht." }
    ],
    deliverables: ["Storyboard and style frames for approval before rendering", "Film in 4K, plus cuts for web, social and event screens", "Music and sound design, licensed for your channels", "Two rounds of revisions on the edit", "Stills from the film as extra marketing images at no charge"],
    deliverablesDe: ["Storyboard und Styleframes zur Freigabe vor dem Rendering", "Film in 4K, dazu Schnitte für Web, Social Media und Bildschirme am Anlass", "Musik und Sounddesign, lizenziert für Ihre Kanäle", "Zwei Korrekturrunden am Schnitt", "Standbilder aus dem Film als zusätzliche Marketingbilder ohne Aufpreis"],
    investment: { from: 4900, unit: "per 60-second film", unitDe: "pro 60-Sekunden-Film", includes: ["Storyboard and style frames", "Camera animation from existing or new scenes", "Music, sound and colour grading", "4K master plus social cuts"], includesDe: ["Storyboard und Styleframes", "Kameraanimation aus bestehenden oder neuen Szenen", "Musik, Sound und Farbkorrektur", "4K-Master plus Social-Media-Schnitte"], turnaround: "3–5 weeks depending on length; 2 weeks when the scenes already exist from your renderings", turnaroundDe: "3–5 Wochen je nach Länge; 2 Wochen, wenn die Szenen aus Ihren Renderings bereits bestehen", revisions: 2 },
    faq: [
      { q: "How long should an architectural animation be?", qDe: "Wie lang sollte eine Architekturanimation sein?", a: "Forty-five to ninety seconds for a website or a sales event; fifteen to thirty seconds for social media. We usually deliver one master and shorter cuts from it, so you do not pay for a second film.", aDe: "Fünfundvierzig bis neunzig Sekunden für Website oder Verkaufsanlass; fünfzehn bis dreissig Sekunden für Social Media. Wir liefern in der Regel einen Master und kürzere Schnitte daraus, damit Sie keinen zweiten Film bezahlen." },
      { q: "How much does an architectural animation cost in Switzerland?", qDe: "Was kostet eine Architekturanimation in der Schweiz?", a: "From CHF 4,900 for a sixty-second film when the scenes already exist from our renderings. A film built from scratch, with new scenes, is quoted on the storyboard — typically from CHF 9,000. Fixed price after the briefing.", aDe: "Ab CHF 4'900 für einen sechzigsekündigen Film, wenn die Szenen aus unseren Renderings bereits bestehen. Ein Film von Grund auf, mit neuen Szenen, wird nach dem Storyboard offeriert — typischerweise ab CHF 9'000. Fixpreis nach dem Briefing." },
      { q: "Does the animation include animated people and traffic?", qDe: "Enthält die Animation animierte Menschen und Verkehr?", a: "Yes. Animated people, traffic, birds and vegetation moving in the wind are part of every film; they are what makes a scene feel inhabited rather than modelled.", aDe: "Ja. Animierte Menschen, Verkehr, Vögel und Vegetation im Wind gehören zu jedem Film; sie machen aus einer modellierten Szene eine bewohnte." },
      { q: "Can we use our own music in the mood film?", qDe: "Können wir im Mood Film eigene Musik verwenden?", a: "If you hold the licence, yes. Otherwise we license a track for your channels — website, social media, events — and the licence is included in the price.", aDe: "Wenn Sie die Lizenz halten, ja. Andernfalls lizenzieren wir einen Titel für Ihre Kanäle — Website, Social Media, Anlässe — und die Lizenz ist im Preis enthalten." },
      { q: "How do revisions work on an architectural animation?", qDe: "Wie laufen Korrekturen bei einer Architekturanimation?", a: "You approve the storyboard and the style frames first, then a low-resolution preview of the full edit. Two rounds on that preview are included. Changes after the final render — a different camera path, new architecture — are quoted separately.", aDe: "Sie geben zuerst Storyboard und Styleframes frei, dann eine niedrig aufgelöste Vorschau des ganzen Schnitts. Zwei Runden an dieser Vorschau sind inbegriffen. Änderungen nach dem finalen Rendering — ein anderer Kamerapfad, neue Architektur — werden separat offeriert." },
      { q: "In which formats is the animation delivered?", qDe: "In welchen Formaten wird die Animation geliefert?", a: "MP4 (H.264) in 4K and Full HD for the master, 16:9, 9:16 and 1:1 cuts for social media, and a WebM version for fast loading on your website. ProRes on request for broadcast or events.", aDe: "MP4 (H.264) in 4K und Full HD für den Master, Schnitte in 16:9, 9:16 und 1:1 für Social Media sowie eine WebM-Version für schnelles Laden auf Ihrer Website. ProRes auf Wunsch für Broadcast oder Anlässe." }
    ]
  },

  "bird-eye-visualization": {
    intro: "A development is bought for its location as much as its apartments: the school, the station, the lake behind the trees. The bird's-eye view is the one image that shows all of it — the project, its neighbours and the way to the tram — in a single glance.",
    introDe: "Eine Überbauung wird genauso für ihre Lage gekauft wie für ihre Wohnungen: die Schule, der Bahnhof, der See hinter den Bäumen. Die Vogelperspektive ist das eine Bild, das alles zeigt — das Projekt, seine Nachbarn und den Weg zum Tram — auf einen Blick.",
    problems: [
      { problem: "The site plan explains nothing to a buyer", problemDe: "Der Situationsplan erklärt einem Käufer nichts", title: "The whole project in one picture", titleDe: "Das ganze Projekt in einem Bild", desc: "Buildings, courtyards, parking entrances, the playground: a bird's-eye view shows how the ensemble works and where each unit sits. It becomes the key visual of the brochure and the navigation image on the project website.", descDe: "Gebäude, Höfe, Einstellhalleneinfahrten, der Spielplatz: Eine Vogelperspektive zeigt, wie das Ensemble funktioniert und wo jede Wohnung liegt. Sie wird zum Schlüsselbild der Broschüre und zum Navigationsbild auf der Projektwebsite." },
      { problem: "The surroundings are the selling point", problemDe: "Die Umgebung ist das Verkaufsargument", title: "Real context from real data", titleDe: "Echter Kontext aus echten Daten", desc: "We build the terrain from the cantonal elevation model and the neighbourhood from satellite imagery and drone photos, so the lake, the forest edge and the motorway are exactly where they are — not where a brochure would like them to be.", descDe: "Wir bauen das Gelände aus dem kantonalen Höhenmodell und das Quartier aus Satellitenbildern und Drohnenfotos, damit See, Waldrand und Autobahn genau dort sind, wo sie liegen — nicht dort, wo eine Broschüre sie gern hätte." },
      { problem: "The council needs to see the impact", problemDe: "Der Gemeinderat muss die Wirkung sehen", title: "An image for the hearing", titleDe: "Ein Bild für die Anhörung", desc: "For a building permit or a design competition, a neutral aerial — correct heights, correct shadows, no marketing gloss — shows the new volume in its town honestly. We deliver that version and the atmospheric one from the same model.", descDe: "Für ein Baugesuch oder einen Wettbewerb zeigt ein neutrales Luftbild — korrekte Höhen, korrekte Schatten, kein Marketing-Glanz — das neue Volumen ehrlich in seiner Gemeinde. Wir liefern diese Version und die stimmungsvolle aus demselben Modell." }
    ],
    deliverables: ["Aerial views at 6K or larger, for brochure covers and billboards", "Terrain and surroundings from elevation, satellite and drone data", "Neutral version for permits and an atmospheric version for marketing", "Two rounds of revisions", "The context model reused for animation and the fly-around navigator"],
    deliverablesDe: ["Luftbilder in 6K oder grösser, für Broschürentitel und Bautafeln", "Gelände und Umgebung aus Höhen-, Satelliten- und Drohnendaten", "Neutrale Version für Bewilligungen und stimmungsvolle Version fürs Marketing", "Zwei Korrekturrunden", "Das Umgebungsmodell wird für Animation und Navigator weiterverwendet"],
    investment: { from: 890, unit: "per view", unitDe: "pro Ansicht", includes: ["Terrain and neighbourhood model", "Camera study for approval", "Two revision rounds", "6K delivery for large-format print"], includesDe: ["Gelände- und Quartiermodell", "Kamerastudie zur Freigabe", "Zwei Korrekturrunden", "Lieferung in 6K für grossformatigen Druck"], turnaround: "7–10 working days for the first view, 3 days for each further angle", turnaroundDe: "7–10 Arbeitstage für die erste Ansicht, 3 Tage für jeden weiteren Winkel", revisions: 2 },
    faq: [
      { q: "Does a bird's-eye visualisation need a drone flight?", qDe: "Braucht eine Vogelperspektive einen Drohnenflug?", a: "Not necessarily. We can build the surroundings from satellite imagery and the cantonal elevation model. A drone photo from the planned camera position makes the result more precise and is the right choice when the surroundings carry the sale — we can arrange one.", aDe: "Nicht zwingend. Wir können die Umgebung aus Satellitenbildern und dem kantonalen Höhenmodell aufbauen. Ein Drohnenfoto aus der geplanten Kameraposition macht das Ergebnis präziser und ist die richtige Wahl, wenn die Umgebung den Verkauf trägt — wir organisieren ihn." },
      { q: "How large can an aerial rendering be printed?", qDe: "Wie gross kann ein Luftbild-Rendering gedruckt werden?", a: "We render aerials at 6,000 pixels on the long edge as standard, enough for a construction-site billboard. Larger formats are rendered on request.", aDe: "Wir rendern Luftbilder standardmässig mit 6'000 Pixeln an der langen Kante, genug für eine Bautafel. Grössere Formate rendern wir auf Anfrage." },
      { q: "Can the aerial view's model be reused for animation and navigator?", qDe: "Kann das Modell der Vogelperspektive für Animation und Navigator weiterverwendet werden?", a: "Yes. The terrain and context model is the base for the animation's opening flight and for the 360° fly-around navigator. Ordering them together saves the context work twice over.", aDe: "Ja. Das Gelände- und Umgebungsmodell ist die Basis für den Eröffnungsflug der Animation und für den 360°-Navigator. Gemeinsam bestellt, sparen Sie die Kontextarbeit zweimal." },
      { q: "How long does a bird's-eye visualisation take?", qDe: "Wie lange dauert eine Vogelperspektive?", a: "Seven to ten working days for the first aerial, because the surroundings take longer than the building. Each further angle from the same model takes about three days.", aDe: "Sieben bis zehn Arbeitstage für das erste Luftbild, weil die Umgebung länger dauert als das Gebäude. Jeder weitere Winkel aus demselben Modell dauert etwa drei Tage." },
      { q: "Can the aerial view show unit numbers and surroundings labels?", qDe: "Kann die Vogelperspektive Wohnungsnummern und Umgebung beschriften?", a: "Yes. We deliver a clean image and a labelled version with unit numbers, building names or points of interest on separate layers, so your graphic team can adapt them.", aDe: "Ja. Wir liefern ein sauberes Bild und eine beschriftete Version mit Wohnungsnummern, Gebäudenamen oder Orientierungspunkten auf separaten Ebenen, damit Ihr Grafikteam sie anpassen kann." },
      { q: "Are aerial renderings accepted for Swiss building permits?", qDe: "Werden Luftbild-Renderings für Baugesuche in der Schweiz akzeptiert?", a: "The neutral version — true heights from your plans, correct sun position for the date, no atmospheric effects — is prepared for exactly that. Several Swiss municipalities have accepted our aerials in permit documentation.", aDe: "Die neutrale Version — echte Höhen aus Ihren Plänen, korrekter Sonnenstand zum Datum, keine Stimmungseffekte — ist genau dafür gemacht. Mehrere Schweizer Gemeinden haben unsere Luftbilder in Baugesuchsunterlagen akzeptiert." }
    ]
  },

  "360-virtual-tour": {
    intro: "A show apartment costs six figures and exists in one place. A 360° tour costs a fraction, runs on every phone, and lets a buyer in Munich walk through a flat in Zurich on a Sunday evening — kitchen to balcony to bedroom, at their own pace, before they call you.",
    introDe: "Eine Musterwohnung kostet sechsstellig und steht an einem Ort. Ein 360°-Rundgang kostet einen Bruchteil, läuft auf jedem Smartphone und lässt einen Käufer in München an einem Sonntagabend durch eine Wohnung in Zürich gehen — Küche, Balkon, Schlafzimmer, im eigenen Tempo, bevor er Sie anruft.",
    problems: [
      { problem: "No show apartment for two years", problemDe: "Zwei Jahre lang keine Musterwohnung", title: "Walk through it before it is built", titleDe: "Durchgehen, bevor es gebaut ist", desc: "Five to six connected rooms per apartment type, rendered from the same scenes as the stills. Hotspots lead from room to room, a floor plan shows where you stand, and every room has its own link for listings and emails.", descDe: "Fünf bis sechs verbundene Räume pro Wohnungstyp, gerendert aus denselben Szenen wie die Standbilder. Hotspots führen von Raum zu Raum, ein Grundriss zeigt, wo man steht, und jeder Raum hat seinen eigenen Link für Inserate und E-Mails." },
      { problem: "Viewings cost sales time", problemDe: "Besichtigungen kosten Verkaufszeit", title: "Pre-qualified enquiries", titleDe: "Vorqualifizierte Anfragen", desc: "People who have walked the tour arrive at the viewing already convinced of the layout and ask about the contract. The tour runs in the browser without an app, on the project website or standalone, and reports which rooms get the most time.", descDe: "Wer den Rundgang gemacht hat, kommt zur Besichtigung bereits vom Grundriss überzeugt und fragt nach dem Vertrag. Der Rundgang läuft im Browser ohne App, auf der Projektwebsite oder eigenständig, und zeigt, welche Räume am längsten angeschaut werden." },
      { problem: "The brochure cannot show the view", problemDe: "Die Broschüre kann die Aussicht nicht zeigen", title: "The real view from the real window", titleDe: "Die echte Aussicht aus dem echten Fenster", desc: "With a drone panorama from the planned floor height, the tour shows the actual view from the fourth-floor balcony — the lake, the Alps, the neighbour's roof — which is the detail that sells the top units first.", descDe: "Mit einem Drohnenpanorama aus der geplanten Geschosshöhe zeigt der Rundgang die tatsächliche Aussicht vom Balkon im vierten Stock — See, Alpen, das Dach des Nachbarn — das Detail, das die obersten Wohnungen zuerst verkauft." }
    ],
    deliverables: ["Browser-based tour, phone and desktop, no app and no plugin", "5–6 rendered panoramas per apartment type at 8K", "Floor plan navigation, hotspots, room notes, your project branding", "A link per room and an embed code for your website", "Hosting included for the sales period"],
    deliverablesDe: ["Browserbasierter Rundgang, Smartphone und Desktop, ohne App und Plugin", "5–6 gerenderte Panoramen pro Wohnungstyp in 8K", "Grundrissnavigation, Hotspots, Raumnotizen, Ihr Projektbranding", "Ein Link pro Raum und ein Einbettungscode für Ihre Website", "Hosting für die Verkaufsphase inbegriffen"],
    investment: { from: 1900, unit: "per apartment type", unitDe: "pro Wohnungstyp", includes: ["5–6 panoramas from the interior scenes", "Tour build with navigation and branding", "Two revision rounds", "Hosting for 24 months"], includesDe: ["5–6 Panoramen aus den Innenraumszenen", "Aufbau des Rundgangs mit Navigation und Branding", "Zwei Korrekturrunden", "Hosting für 24 Monate"], turnaround: "2–3 weeks; 1 week when the interior scenes already exist", turnaroundDe: "2–3 Wochen; 1 Woche, wenn die Innenraumszenen bereits bestehen", revisions: 2 },
    faq: [
      { q: "Does a 360° virtual tour work on a phone?", qDe: "Funktioniert ein 360°-Rundgang auf dem Smartphone?", a: "Yes. The tour runs in the browser on any phone, tablet or desktop; on a phone you look around by touch or by moving the device. No app, no download. VR headsets are supported through the same link.", aDe: "Ja. Der Rundgang läuft im Browser auf jedem Smartphone, Tablet oder Desktop; am Smartphone schaut man sich per Touch oder durch Bewegen des Geräts um. Keine App, kein Download. VR-Brillen werden über denselben Link unterstützt." },
      { q: "Can the 360° tour be embedded on our own website?", qDe: "Kann der 360°-Rundgang auf unserer Website eingebettet werden?", a: "Yes, with an embed code or a link. Every room has its own URL, so a listing can link straight to the kitchen. We also build project websites around the tour if you do not have one.", aDe: "Ja, per Einbettungscode oder Link. Jeder Raum hat seine eigene URL, ein Inserat kann also direkt in die Küche verlinken. Wir bauen auch Projektwebsites um den Rundgang herum, falls Sie keine haben." },
      { q: "How much does a 360° virtual tour cost?", qDe: "Was kostet ein 360°-Rundgang?", a: "From CHF 1,900 per apartment type when we have already rendered its interiors — the panoramas come from the same scenes. Built from scratch, a five-room tour is typically from CHF 3,400. Hosting for the sales period is included.", aDe: "Ab CHF 1'900 pro Wohnungstyp, wenn wir die Innenräume bereits gerendert haben — die Panoramen stammen aus denselben Szenen. Von Grund auf kostet ein Rundgang mit fünf Räumen typischerweise ab CHF 3'400. Hosting für die Verkaufsphase ist inbegriffen." },
      { q: "How long is the virtual tour hosted?", qDe: "Wie lange wird der virtuelle Rundgang gehostet?", a: "Twenty-four months are included, which covers most sales periods. After that, hosting is CHF 30 per month or we hand you the files to host yourself.", aDe: "Vierundzwanzig Monate sind inbegriffen, das deckt die meisten Verkaufsphasen ab. Danach kostet das Hosting CHF 30 pro Monat, oder wir übergeben Ihnen die Dateien zum Selberhosten." },
      { q: "Can we track who views the 360° tour?", qDe: "Können wir auswerten, wer den 360°-Rundgang anschaut?", a: "The tour reports views, time per room and which hotspots are used, without cookies. If you need lead capture, a contact form can open from inside the tour.", aDe: "Der Rundgang meldet Aufrufe, Zeit pro Raum und genutzte Hotspots, ohne Cookies. Wenn Sie Leads erfassen möchten, lässt sich ein Kontaktformular aus dem Rundgang heraus öffnen." },
      { q: "Can the virtual tour show the real view from the window?", qDe: "Kann der virtuelle Rundgang die echte Aussicht aus dem Fenster zeigen?", a: "Yes, with a drone panorama taken at the planned floor height, which we composite behind the rendered windows. We organise the flight with a licensed pilot in Switzerland, Germany and Austria.", aDe: "Ja, mit einem Drohnenpanorama in der geplanten Geschosshöhe, das wir hinter die gerenderten Fenster montieren. Den Flug organisieren wir mit einem lizenzierten Piloten in der Schweiz, Deutschland und Österreich." }
    ]
  },

  "cinemagraph-live-shot": {
    intro: "In a feed of still images, the one where the curtain moves gets the thumb to stop. A cinemagraph is a finished rendering with a single living detail — fire, water, leaves, a passing cloud — looped so it never ends. It costs a fraction of a film and works wherever a still works.",
    introDe: "In einem Feed voller Standbilder stoppt der Daumen bei dem, in dem sich der Vorhang bewegt. Ein Cinemagraph ist ein fertiges Rendering mit einem einzigen lebendigen Detail — Feuer, Wasser, Blätter, eine ziehende Wolke — als Endlosschleife. Es kostet einen Bruchteil eines Films und funktioniert überall, wo ein Standbild funktioniert.",
    problems: [
      { problem: "Social posts with renders get scrolled past", problemDe: "Posts mit Renderings werden weitergescrollt", title: "Motion that stops the scroll", titleDe: "Bewegung, die das Scrollen stoppt", desc: "A fireplace burning in the living room, rain on the window, steam from the coffee. One moving element in an otherwise still image reads as life, and platforms rank it as video — more reach for the same picture.", descDe: "Ein brennendes Cheminée im Wohnzimmer, Regen am Fenster, Dampf vom Kaffee. Ein bewegtes Element in einem sonst stillen Bild wirkt wie Leben, und die Plattformen werten es als Video — mehr Reichweite für dasselbe Bild." },
      { problem: "A film is out of budget for a single listing", problemDe: "Ein Film sprengt das Budget für ein einzelnes Inserat", title: "Film effect at still-image cost", titleDe: "Filmwirkung zum Preis eines Standbilds", desc: "Because the cinemagraph is built on a rendering that already exists, the work is the moving layer, not a new scene. A set of three for a project launch is done in a week.", descDe: "Weil das Cinemagraph auf einem bereits bestehenden Rendering aufbaut, besteht die Arbeit aus der bewegten Ebene, nicht aus einer neuen Szene. Ein Set von dreien für einen Projektstart ist in einer Woche fertig." },
      { problem: "The website hero feels static", problemDe: "Der Website-Hero wirkt statisch", title: "A hero that breathes", titleDe: "Ein Hero, der atmet", desc: "Delivered as a light, seamless loop, a cinemagraph replaces a hero video at a tenth of the file size: it loads instantly on a phone and never shows a loading spinner.", descDe: "Als leichte, nahtlose Schleife geliefert, ersetzt ein Cinemagraph ein Hero-Video mit einem Zehntel der Dateigrösse: Es lädt sofort auf dem Smartphone und zeigt nie einen Ladekreis." }
    ],
    deliverables: ["Seamless loop, 6–12 seconds, from an existing or new rendering", "MP4 and WebM for web, plus GIF and vertical cuts for social", "One moving element per image, more on request", "One round of revisions on the motion", "The still image included at full resolution"],
    deliverablesDe: ["Nahtlose Schleife, 6–12 Sekunden, aus einem bestehenden oder neuen Rendering", "MP4 und WebM fürs Web, dazu GIF und vertikale Schnitte für Social Media", "Ein bewegtes Element pro Bild, mehr auf Wunsch", "Eine Korrekturrunde an der Bewegung", "Das Standbild in voller Auflösung inbegriffen"],
    investment: { from: 490, unit: "per loop", unitDe: "pro Schleife", includes: ["Motion layer on your rendering", "Seamless loop edit", "Web and social formats", "One revision round"], includesDe: ["Bewegungsebene auf Ihrem Rendering", "Nahtloser Schleifenschnitt", "Web- und Social-Media-Formate", "Eine Korrekturrunde"], turnaround: "3–5 working days per loop from an existing rendering", turnaroundDe: "3–5 Arbeitstage pro Schleife aus einem bestehenden Rendering", revisions: 1 },
    faq: [
      { q: "Does a cinemagraph need an existing rendering?", qDe: "Braucht ein Cinemagraph ein bestehendes Rendering?", a: "A cinemagraph is built on a finished image. If we made your renderings, nothing extra is needed. If they were made elsewhere, send the full-resolution file; most renderings can be animated. If no image exists, we quote the still and the loop together.", aDe: "Ein Cinemagraph entsteht auf einem fertigen Bild. Haben wir Ihre Renderings gemacht, braucht es nichts weiter. Stammen sie von anderswo, senden Sie die Datei in voller Auflösung; die meisten Renderings lassen sich animieren. Gibt es noch kein Bild, offerieren wir Standbild und Schleife zusammen." },
      { q: "What can move in an architectural cinemagraph?", qDe: "Was kann sich in einem Architektur-Cinemagraph bewegen?", a: "Fire, water, steam, clouds, leaves, curtains, light, people in the distance, a car passing. The rule is one or two elements: the stillness around them is what makes the motion noticeable.", aDe: "Feuer, Wasser, Dampf, Wolken, Blätter, Vorhänge, Licht, Menschen in der Ferne, ein vorbeifahrendes Auto. Die Regel: ein oder zwei Elemente — die Ruhe darum herum macht die Bewegung erst sichtbar." },
      { q: "Where can a cinemagraph be used in real estate marketing?", qDe: "Wo lässt sich ein Cinemagraph im Immobilienmarketing einsetzen?", a: "Instagram, LinkedIn and Facebook posts and stories, a website hero, a digital billboard, an email header. We deliver the formats for each; the loop plays without sound.", aDe: "Instagram-, LinkedIn- und Facebook-Posts und Stories, ein Website-Hero, eine digitale Plakatwand, ein E-Mail-Header. Wir liefern die Formate für jeden Kanal; die Schleife läuft ohne Ton." },
      { q: "How long is a cinemagraph loop?", qDe: "Wie lang ist eine Cinemagraph-Schleife?", a: "Six to twelve seconds, cut so the end meets the beginning without a visible jump. Platforms that cap video length still play the full loop.", aDe: "Sechs bis zwölf Sekunden, so geschnitten, dass das Ende ohne sichtbaren Sprung an den Anfang anschliesst. Auch Plattformen mit Längenlimit spielen die ganze Schleife." },
      { q: "How much does a cinemagraph cost?", qDe: "Was kostet ein Cinemagraph?", a: "From CHF 490 per loop on an existing rendering. A set of three for a launch is CHF 1,300. If the still has to be rendered first, the exterior or interior rate applies in addition.", aDe: "Ab CHF 490 pro Schleife auf einem bestehenden Rendering. Ein Set von dreien für einen Projektstart kostet CHF 1'300. Muss das Standbild erst gerendert werden, kommt der Aussen- oder Innenraumtarif hinzu." },
      { q: "How fast is a cinemagraph delivered?", qDe: "Wie schnell wird ein Cinemagraph geliefert?", a: "Three to five working days per loop. A set of three is usually ready within a week.", aDe: "Drei bis fünf Arbeitstage pro Schleife. Ein Set von dreien ist in der Regel innerhalb einer Woche fertig." }
    ]
  },

  "product-visualization": {
    intro: "A photo shoot needs the product to exist, a studio, a day and a photographer. A rendering needs the CAD file. For a kitchen in twelve fronts, a tap in three finishes or a chair that is still a prototype, the rendering is faster, cheaper and identical from one image to the next.",
    introDe: "Ein Fotoshooting braucht das fertige Produkt, ein Studio, einen Tag und einen Fotografen. Ein Rendering braucht die CAD-Datei. Für eine Küche in zwölf Fronten, eine Armatur in drei Oberflächen oder einen Stuhl, der noch Prototyp ist, ist das Rendering schneller, günstiger und von Bild zu Bild identisch.",
    problems: [
      { problem: "The catalogue needs every variant", problemDe: "Der Katalog braucht jede Variante", title: "Twelve finishes from one scene", titleDe: "Zwölf Oberflächen aus einer Szene", desc: "Once the product and the set are built, every colour, material and configuration is a render pass, not a reshoot. The light, the angle and the shadow stay identical across the whole range — which a photo shoot cannot promise.", descDe: "Stehen Produkt und Set, ist jede Farbe, jedes Material und jede Konfiguration ein Renderdurchlauf, kein neues Shooting. Licht, Winkel und Schatten bleiben über die ganze Serie identisch — was ein Fotoshooting nicht versprechen kann." },
      { problem: "The product does not exist yet", problemDe: "Das Produkt existiert noch nicht", title: "Launch imagery before production", titleDe: "Launch-Bilder vor der Produktion", desc: "From the manufacturer's CAD data we render the product as it will be made, down to the grain of the veneer and the brushing of the steel. Pre-orders, trade fair walls and the online shop are ready on the day the first unit leaves the factory.", descDe: "Aus den CAD-Daten des Herstellers rendern wir das Produkt, wie es gebaut wird, bis zur Maserung des Furniers und zum Schliff des Stahls. Vorbestellungen, Messewände und der Onlineshop stehen an dem Tag, an dem das erste Stück die Fabrik verlässt." },
      { problem: "Products need a room, not a white box", problemDe: "Produkte brauchen einen Raum, keine weisse Box", title: "Shown where it will live", titleDe: "Gezeigt, wo es stehen wird", desc: "Packshots on white for the shop, and the same product in a styled kitchen, bathroom or living room for the campaign. We build the interior around the product so the material and scale read correctly.", descDe: "Packshots auf Weiss für den Shop, und dasselbe Produkt in einer gestylten Küche, einem Bad oder Wohnzimmer für die Kampagne. Wir bauen den Innenraum um das Produkt, damit Material und Grösse richtig wirken." }
    ],
    deliverables: ["Packshots on white or transparent background at 6K", "Lifestyle scenes with the product in a styled interior", "Colour and material variants from the same setup", "Two rounds of revisions", "Files prepared for web shop, print catalogue and trade fair"],
    deliverablesDe: ["Packshots auf weissem oder transparentem Hintergrund in 6K", "Lifestyle-Szenen mit dem Produkt in einem gestylten Innenraum", "Farb- und Materialvarianten aus demselben Setup", "Zwei Korrekturrunden", "Dateien aufbereitet für Onlineshop, Printkatalog und Messe"],
    investment: { from: 390, unit: "per shot", unitDe: "pro Aufnahme", includes: ["Product modelling or CAD import", "Studio or interior set", "Two revision rounds", "6K delivery, web and print"], includesDe: ["Produktmodellierung oder CAD-Import", "Studio- oder Innenraum-Set", "Zwei Korrekturrunden", "Lieferung in 6K, Web und Print"], turnaround: "3–5 working days for the first shot, 1 day per variant from the same setup", turnaroundDe: "3–5 Arbeitstage für die erste Aufnahme, 1 Tag pro Variante aus demselben Setup", revisions: 2 },
    faq: [
      { q: "What data do you need for a product visualisation?", qDe: "Welche Daten brauchen Sie für eine Produktvisualisierung?", a: "CAD files (STEP, IGES, SolidWorks, Rhino) are ideal; drawings with dimensions and photos work too, with modelling quoted separately. Material samples or supplier references for finishes and fabrics.", aDe: "CAD-Dateien (STEP, IGES, SolidWorks, Rhino) sind ideal; Zeichnungen mit Massen und Fotos gehen auch, die Modellierung wird dann separat offeriert. Materialmuster oder Lieferantenreferenzen für Oberflächen und Stoffe." },
      { q: "How much does a product rendering variant cost?", qDe: "Was kostet eine Variante eines Produktrenderings?", a: "The first shot of a product is from CHF 390; each colour or material variant from the same camera and set is from CHF 90, because only the material changes.", aDe: "Die erste Aufnahme eines Produkts kostet ab CHF 390; jede Farb- oder Materialvariante aus derselben Kamera und demselben Set ab CHF 90, weil sich nur das Material ändert." },
      { q: "Can product renderings match our existing photography?", qDe: "Können Produktrenderings zu unserer bestehenden Fotografie passen?", a: "Yes. Send a few photos from your current catalogue and we match the lighting, background and camera, so renderings and photos sit side by side without a visible difference.", aDe: "Ja. Senden Sie ein paar Fotos aus Ihrem aktuellen Katalog, und wir gleichen Licht, Hintergrund und Kamera an, damit Renderings und Fotos ohne sichtbaren Unterschied nebeneinander stehen." },
      { q: "Do you also do product animations?", qDe: "Machen Sie auch Produktanimationen?", a: "Yes: 360° turntables, exploded views and short feature clips for the shop page or trade fair screen, from the same model as the stills.", aDe: "Ja: 360°-Drehungen, Explosionsdarstellungen und kurze Feature-Clips für die Shopseite oder den Messebildschirm, aus demselben Modell wie die Standbilder." },
      { q: "How does product visualisation compare with photography?", qDe: "Wie schneidet Produktvisualisierung im Vergleich zur Fotografie ab?", a: "Indistinguishable at catalogue scale when the material data is good. For fabrics and natural wood we work from physical samples or high-resolution scans, which is where renderings most often give themselves away.", aDe: "Im Katalogmassstab nicht zu unterscheiden, wenn die Materialdaten gut sind. Bei Stoffen und Naturholz arbeiten wir mit physischen Mustern oder hochauflösenden Scans — dort verraten sich Renderings sonst am ehesten." },
      { q: "How fast can a full product range be rendered?", qDe: "Wie schnell lässt sich eine ganze Produktserie rendern?", a: "After the first approved shot, a range of twenty variants is usually delivered within a week. Tell us the catalogue deadline and we plan backwards from it.", aDe: "Nach der ersten freigegebenen Aufnahme ist eine Serie von zwanzig Varianten in der Regel innerhalb einer Woche geliefert. Nennen Sie uns den Katalogtermin, und wir planen rückwärts." }
    ]
  },

  "virtual-staging": {
    intro: "An empty apartment photographs as small, cold and hard to price. The same photo with a sofa, a dining table and a lamp in the corner reads as a home — and a listing with staged photos gets more enquiries at a better price. Virtual staging does that from the photo, without a truck or a stylist.",
    introDe: "Eine leere Wohnung fotografiert sich klein, kalt und schwer zu bewerten. Dasselbe Foto mit Sofa, Esstisch und einer Lampe in der Ecke liest sich als Zuhause — und ein Inserat mit eingerichteten Fotos bekommt mehr Anfragen zu einem besseren Preis. Virtual Staging macht das aus dem Foto, ohne Lastwagen und Stylist.",
    problems: [
      { problem: "Empty rooms do not sell", problemDe: "Leere Räume verkaufen nicht", title: "Furnished from the photo", titleDe: "Eingerichtet aus dem Foto", desc: "We place real-scale furniture into your photograph, matching the perspective, the light and the shadows, so the result looks photographed rather than pasted. Buyers see how the room is used and how big it really is.", descDe: "Wir setzen Möbel in Originalgrösse in Ihr Foto, passend zu Perspektive, Licht und Schatten, damit das Ergebnis fotografiert aussieht und nicht montiert. Käufer sehen, wie der Raum genutzt wird und wie gross er wirklich ist." },
      { problem: "Physical staging costs thousands per month", problemDe: "Physisches Staging kostet Tausende pro Monat", title: "A fraction of the cost, delivered in days", titleDe: "Ein Bruchteil der Kosten, in Tagen geliefert", desc: "No rental furniture, no transport, no insurance. A whole apartment is staged in two to three days, and a second style for a different buyer group costs little extra.", descDe: "Keine Mietmöbel, kein Transport, keine Versicherung. Eine ganze Wohnung ist in zwei bis drei Tagen eingerichtet, und ein zweiter Stil für eine andere Käufergruppe kostet wenig Aufpreis." },
      { problem: "The existing building needs a before and after", problemDe: "Der Bestand braucht ein Vorher-Nachher", title: "Renovation shown, not promised", titleDe: "Renovation gezeigt, nicht versprochen", desc: "For refurbishments we go beyond furniture: new floors, a new kitchen, repainted walls — in the real photo of the existing room. The before-and-after slider becomes the strongest element of the listing.", descDe: "Bei Sanierungen gehen wir über Möbel hinaus: neue Böden, neue Küche, frisch gestrichene Wände — im echten Foto des bestehenden Raums. Der Vorher-Nachher-Schieberegler wird zum stärksten Element des Inserats." }
    ],
    deliverables: ["Staged photo at the original resolution, ready for the listing", "Furniture style matched to the target buyer, two styles on request", "Renovation variants: floors, kitchen, walls, lighting", "Before-and-after pairs for your website", "One round of revisions per photo"],
    deliverablesDe: ["Eingerichtetes Foto in Originalauflösung, bereit fürs Inserat", "Möbelstil passend zur Zielgruppe, auf Wunsch zwei Stile", "Renovationsvarianten: Böden, Küche, Wände, Beleuchtung", "Vorher-Nachher-Paare für Ihre Website", "Eine Korrekturrunde pro Foto"],
    investment: { from: 190, unit: "per photo", unitDe: "pro Foto", includes: ["Furniture and decor in your photo", "Perspective and light matching", "Listing-ready delivery", "One revision round"], includesDe: ["Möbel und Dekor in Ihrem Foto", "Perspektiv- und Lichtanpassung", "Lieferung bereit fürs Inserat", "Eine Korrekturrunde"], turnaround: "2–3 working days for an apartment of 6–8 photos", turnaroundDe: "2–3 Arbeitstage für eine Wohnung mit 6–8 Fotos", revisions: 1 },
    faq: [
      { q: "What photos do you need for virtual staging?", qDe: "Welche Fotos brauchen Sie für Virtual Staging?", a: "The listing photos as you would publish them: straight, well lit, at full resolution. Wide-angle shots of the main rooms work best. If the photos have not been taken yet, we can brief your photographer.", aDe: "Die Inseratsfotos, wie Sie sie veröffentlichen würden: gerade, gut belichtet, in voller Auflösung. Weitwinkelaufnahmen der Haupträume eignen sich am besten. Sind die Fotos noch nicht gemacht, briefen wir Ihren Fotografen." },
      { q: "Is virtual staging allowed in Swiss, German and Austrian listings?", qDe: "Ist Virtual Staging in Inseraten in der Schweiz, Deutschland und Österreich erlaubt?", a: "Yes, when it is declared. We recommend the note 'virtually staged' on the image or in the listing text and deliver the original photo alongside, which is what the Swiss, German and Austrian portals expect.", aDe: "Ja, wenn es deklariert wird. Wir empfehlen den Hinweis «virtuell eingerichtet» im Bild oder im Inseratstext und liefern das Originalfoto mit — das erwarten die Portale in der Schweiz, Deutschland und Österreich." },
      { q: "Can virtual staging remove the existing furniture first?", qDe: "Kann Virtual Staging die bestehenden Möbel zuerst entfernen?", a: "Yes. Clearing an occupied room — furniture, clutter, cables — is CHF 60 per photo on top, then it is staged like an empty one.", aDe: "Ja. Das Leerräumen eines bewohnten Zimmers — Möbel, Krimskrams, Kabel — kostet CHF 60 pro Foto extra, danach wird es wie ein leerer Raum eingerichtet." },
      { q: "Which furnishing styles does virtual staging offer?", qDe: "Welche Einrichtungsstile bietet Virtual Staging?", a: "Scandinavian, contemporary, classic, loft and family are the usual requests; we also match a style to your project's brochure. Tell us who the buyer is and we propose one.", aDe: "Skandinavisch, zeitgenössisch, klassisch, Loft und Familie sind die üblichen Wünsche; wir stimmen den Stil auch auf Ihre Projektbroschüre ab. Sagen Sie uns, wer der Käufer ist, und wir schlagen einen vor." },
      { q: "How fast is virtual staging delivered?", qDe: "Wie schnell wird Virtual Staging geliefert?", a: "Two to three working days for an apartment of six to eight photos. Single photos within 24 hours on request.", aDe: "Zwei bis drei Arbeitstage für eine Wohnung mit sechs bis acht Fotos. Einzelne Fotos auf Wunsch innerhalb von 24 Stunden." },
      { q: "Can virtual staging be applied to a rendering instead of a photo?", qDe: "Lässt sich Virtual Staging auf ein Rendering statt auf ein Foto anwenden?", a: "For a new build, yes — though then it is usually better to render the interior fully, because the scene can be reused for other views and the 360° tour. We advise which route is cheaper for your case.", aDe: "Bei einem Neubau ja — dann ist es aber meist besser, den Innenraum komplett zu rendern, weil die Szene für weitere Ansichten und den 360°-Rundgang wiederverwendet werden kann. Wir beraten, welcher Weg in Ihrem Fall günstiger ist." }
    ]
  },

  "graphic-design": {
    intro: "The renderings are done; now they have to reach the buyer. The brochure on the sales table, the banner on the construction fence, the logo on the sign at the site entrance — designed by the people who made the images, so the project looks like one project everywhere it appears.",
    introDe: "Die Renderings sind fertig; jetzt müssen sie zum Käufer. Die Broschüre auf dem Verkaufstisch, das Banner am Bauzaun, das Logo auf der Tafel an der Einfahrt — gestaltet von denen, die die Bilder gemacht haben, damit das Projekt überall wie ein Projekt aussieht.",
    problems: [
      { problem: "The brochure is built from whatever was to hand", problemDe: "Die Broschüre entsteht aus dem, was gerade da war", title: "A sales dossier with a layout", titleDe: "Eine Verkaufsdokumentation mit Layout", desc: "Cover, project story, site plan, unit pages with floor plans and renderings, finish schedule, contact — designed as a sequence a buyer reads in order. Print-ready PDF and an interactive version for email.", descDe: "Titel, Projektgeschichte, Situationsplan, Wohnungsseiten mit Grundrissen und Renderings, Ausbaubeschrieb, Kontakt — gestaltet als Abfolge, die ein Käufer der Reihe nach liest. Druckfertiges PDF und eine interaktive Version für E-Mail." },
      { problem: "The project has no name and no face", problemDe: "Das Projekt hat keinen Namen und kein Gesicht", title: "Naming, logo and a visual system", titleDe: "Naming, Logo und ein visuelles System", desc: "A name that works in German and English, a wordmark, a colour and type system — small enough to apply in an afternoon, consistent enough that the fence banner, the website and the brochure are recognisably the same project.", descDe: "Ein Name, der auf Deutsch und Englisch funktioniert, eine Wortmarke, ein Farb- und Schriftsystem — klein genug, um es an einem Nachmittag anzuwenden, konsistent genug, dass Bauzaun, Website und Broschüre erkennbar dasselbe Projekt sind." },
      { problem: "The site is the best billboard and it is empty", problemDe: "Die Baustelle ist die beste Plakatwand und sie ist leer", title: "Fence banners, signs and the site board", titleDe: "Bauzaunbanner, Tafeln und die Bautafel", desc: "Large-format files set up for the printer — bleed, resolution, colour profile — with the rendering at the size it deserves and the phone number readable from the passing tram.", descDe: "Grossformatdateien, eingerichtet für die Druckerei — Beschnitt, Auflösung, Farbprofil — mit dem Rendering in der Grösse, die es verdient, und der Telefonnummer, die man aus dem vorbeifahrenden Tram lesen kann." }
    ],
    deliverables: ["Sales brochure, print-ready and interactive PDF", "Project naming, logo and a short style guide", "Construction fence banners, site board and signage files", "Social media templates in your project style", "Open files and fonts handed over for your own use"],
    deliverablesDe: ["Verkaufsbroschüre als druckfertiges und interaktives PDF", "Projektname, Logo und ein kurzer Styleguide", "Bauzaunbanner, Bautafel und Beschilderungsdateien", "Social-Media-Vorlagen in Ihrem Projektstil", "Offene Dateien und Schriften zur eigenen Verwendung übergeben"],
    investment: { from: 1400, unit: "per brochure (8 pages)", unitDe: "pro Broschüre (8 Seiten)", includes: ["Layout concept and two design directions", "Typesetting of your texts and plans", "Two revision rounds", "Print-ready and screen PDF"], includesDe: ["Layoutkonzept und zwei Gestaltungsrichtungen", "Satz Ihrer Texte und Pläne", "Zwei Korrekturrunden", "PDF druckfertig und für den Bildschirm"], turnaround: "1–2 weeks for a brochure; logo and style guide 2 weeks", turnaroundDe: "1–2 Wochen für eine Broschüre; Logo und Styleguide 2 Wochen", revisions: 2 },
    faq: [
      { q: "Do you also write the texts for the sales brochure?", qDe: "Schreiben Sie auch die Texte für die Verkaufsbroschüre?", a: "We set the texts you provide and edit them for length and tone. Writing from scratch — project story, location description — is available in German and English at an hourly rate.", aDe: "Wir setzen die Texte, die Sie liefern, und redigieren sie auf Länge und Tonalität. Texten von Grund auf — Projektgeschichte, Lagebeschrieb — bieten wir auf Deutsch und Englisch zum Stundensatz an." },
      { q: "Can the real estate branding follow our corporate design?", qDe: "Kann das Immobilien-Branding unserem Corporate Design folgen?", a: "Yes. Send the brand manual and the fonts and we design within it. If the project should have its own identity next to the company brand, we propose how the two relate.", aDe: "Ja. Senden Sie uns das Brand Manual und die Schriften, und wir gestalten darin. Soll das Projekt neben der Firmenmarke eine eigene Identität haben, schlagen wir vor, wie sich beide zueinander verhalten." },
      { q: "Do you handle the printing of brochures and site banners?", qDe: "Übernehmen Sie den Druck von Broschüren und Bautafeln?", a: "We prepare the files to your printer's specification and check the proof. Printing itself is billed by the printer; we can recommend ones in Switzerland, Germany and Austria.", aDe: "Wir bereiten die Dateien nach den Vorgaben Ihrer Druckerei auf und prüfen den Proof. Der Druck selbst wird von der Druckerei verrechnet; wir empfehlen gern Betriebe in der Schweiz, Deutschland und Österreich." },
      { q: "How much does a real estate sales brochure cost?", qDe: "Was kostet eine Immobilien-Verkaufsbroschüre?", a: "From CHF 1,400 for an eight-page sales brochure with your texts and our renderings. Longer dossiers are quoted per page; a 32-page project book is typically CHF 3,200 to 4,500.", aDe: "Ab CHF 1'400 für eine achtseitige Verkaufsbroschüre mit Ihren Texten und unseren Renderings. Längere Dokumentationen werden pro Seite offeriert; ein 32-seitiges Projektbuch kostet typischerweise CHF 3'200 bis 4'500." },
      { q: "Do we get the open design files?", qDe: "Bekommen wir die offenen Designdateien?", a: "Yes. InDesign or Figma files, the fonts (where the licence allows) and all image assets are handed over at the end, so your team or another agency can update the material later.", aDe: "Ja. InDesign- oder Figma-Dateien, die Schriften (soweit die Lizenz es erlaubt) und alle Bilddaten werden am Ende übergeben, damit Ihr Team oder eine andere Agentur das Material später aktualisieren kann." },
      { q: "How long does a brochure or logo take?", qDe: "Wie lange dauern Broschüre oder Logo?", a: "One to two weeks for a brochure once the texts and plans are final. Naming and logo take about two weeks including two presentation rounds.", aDe: "Ein bis zwei Wochen für eine Broschüre, sobald Texte und Pläne final sind. Naming und Logo dauern etwa zwei Wochen inklusive zwei Präsentationsrunden." }
    ]
  },

  "3d-floorplans": {
    intro: "A 2D floor plan is read by architects. A 3D floor plan is read by everyone: the furniture shows the scale, the colours show the rooms, and the balcony is obviously the balcony. In a listing it is the image buyers spend the most time on after the hero.",
    introDe: "Einen 2D-Grundriss lesen Architekten. Einen 3D-Grundriss lesen alle: Die Möbel zeigen den Massstab, die Farben die Räume, und der Balkon ist offensichtlich der Balkon. Im Inserat ist er das Bild, auf dem Käufer nach dem Hero am längsten bleiben.",
    problems: [
      { problem: "Buyers ask whether the sofa will fit", problemDe: "Käufer fragen, ob das Sofa Platz hat", title: "Scale that needs no explaining", titleDe: "Massstab, der keine Erklärung braucht", desc: "Furniture at real dimensions, door swings, kitchen appliances and the washing machine where the plan puts it. The question about the sofa answers itself, and the viewing starts one step further along.", descDe: "Möbel in echten Massen, Türaufschläge, Küchengeräte und die Waschmaschine dort, wo der Plan sie vorsieht. Die Frage nach dem Sofa beantwortet sich selbst, und die Besichtigung beginnt einen Schritt weiter vorn." },
      { problem: "Twenty unit types, one deadline", problemDe: "Zwanzig Wohnungstypen, ein Termin", title: "A consistent series, fast", titleDe: "Eine durchgehende Serie, schnell", desc: "The same angle, the same furniture family, the same colour code on every plan in the project, so the unit pages of the brochure and the website read as a set. A series of twenty is done in a week.", descDe: "Derselbe Winkel, dieselbe Möbelfamilie, derselbe Farbcode auf jedem Grundriss im Projekt, damit die Wohnungsseiten in Broschüre und Website als Serie lesen. Eine Serie von zwanzig ist in einer Woche fertig." },
      { problem: "The plan has to work in the brochure and on the website", problemDe: "Der Plan muss in Broschüre und Website funktionieren", title: "One plan, every format", titleDe: "Ein Plan, jedes Format", desc: "Delivered as a high-resolution image for print and as a light file for the web, with a clean version and a labelled version (room names, areas, north arrow) on separate layers.", descDe: "Geliefert als hochauflösendes Bild für den Druck und als leichte Datei fürs Web, mit einer sauberen und einer beschrifteten Version (Raumnamen, Flächen, Nordpfeil) auf getrennten Ebenen." }
    ],
    deliverables: ["3D floor plan per unit type, furnished and coloured", "Clean and labelled versions, print and web resolution", "Consistent style across the whole project", "Whole-floor and whole-building overviews on request", "One round of revisions per plan"],
    deliverablesDe: ["3D-Grundriss pro Wohnungstyp, möbliert und farbig", "Saubere und beschriftete Version, in Print- und Webauflösung", "Durchgehender Stil über das ganze Projekt", "Geschoss- und Gebäudeübersichten auf Wunsch", "Eine Korrekturrunde pro Grundriss"],
    investment: { from: 290, unit: "per floor plan", unitDe: "pro Grundriss", includes: ["Modelling from your 2D plan", "Furniture and finishes", "Clean and labelled versions", "One revision round"], includesDe: ["Modellierung aus Ihrem 2D-Plan", "Möblierung und Oberflächen", "Saubere und beschriftete Version", "Eine Korrekturrunde"], turnaround: "3–5 working days for the first plan, then 1 day per plan in the same style", turnaroundDe: "3–5 Arbeitstage für den ersten Grundriss, danach 1 Tag pro Grundriss im selben Stil", revisions: 1 },
    faq: [
      { q: "What do you need for a 3D floor plan?", qDe: "Was brauchen Sie für einen 3D-Grundriss?", a: "The 2D floor plan as DWG or PDF with dimensions, the finish schedule if the floors and kitchen should match the project, and a note on the style — light and Scandinavian, or darker and more urban.", aDe: "Den 2D-Grundriss als DWG oder PDF mit Massen, die Ausbauliste, falls Böden und Küche zum Projekt passen sollen, und einen Hinweis zum Stil — hell und skandinavisch oder dunkler und urbaner." },
      { q: "Are 3D floor plans to scale?", qDe: "Sind 3D-Grundrisse massstabsgetreu?", a: "Yes. They are modelled from your dimensioned plan, so walls, openings and furniture are at their real proportions. For legal purposes the 2D plan remains the reference, and we say so in the footer if you wish.", aDe: "Ja. Sie werden aus Ihrem bemassten Plan modelliert, Wände, Öffnungen und Möbel haben also ihre echten Proportionen. Rechtlich bleibt der 2D-Plan massgebend, und auf Wunsch vermerken wir das in der Fusszeile." },
      { q: "How much does a series of 3D floor plans cost?", qDe: "Was kostet eine Serie von 3D-Grundrissen?", a: "From CHF 290 per plan for the first few; from ten plans in one project the rate drops to CHF 220 per plan, because the furniture library and the style are already set.", aDe: "Ab CHF 290 pro Grundriss für die ersten; ab zehn Grundrissen in einem Projekt sinkt der Preis auf CHF 220 pro Grundriss, weil Möbelbibliothek und Stil bereits stehen." },
      { q: "Can 3D floor plans show the whole floor or building?", qDe: "Können 3D-Grundrisse das ganze Geschoss oder Gebäude zeigen?", a: "Yes: floor overviews with all units, and an exploded building view that shows every floor stacked — useful on the project website as the entry point to the unit list.", aDe: "Ja: Geschossübersichten mit allen Wohnungen und eine Explosionsansicht des Gebäudes mit allen Geschossen übereinander — auf der Projektwebsite nützlich als Einstieg in den Wohnungsspiegel." },
      { q: "How fast are 3D floor plans delivered?", qDe: "Wie schnell werden 3D-Grundrisse geliefert?", a: "Three to five working days for the first plan, which sets the style. After approval, about one plan per day; a series of twenty is delivered within a week.", aDe: "Drei bis fünf Arbeitstage für den ersten Grundriss, der den Stil festlegt. Nach der Freigabe etwa ein Grundriss pro Tag; eine Serie von zwanzig ist innerhalb einer Woche geliefert." },
      { q: "Can 3D floor plans be updated later?", qDe: "Können 3D-Grundrisse später angepasst werden?", a: "Yes. A changed wall or a different kitchen in an existing plan is a small revision at an hourly rate, because the model is kept for the duration of the project.", aDe: "Ja. Eine geänderte Wand oder eine andere Küche in einem bestehenden Grundriss ist eine kleine Korrektur zum Stundensatz, weil das Modell für die Dauer des Projekts aufbewahrt wird." }
    ]
  },

  "fly-around-navigator": {
    intro: "For a development of forty apartments, the question is not 'is it nice' but 'which one is mine'. The navigator is the building you can turn in your hands: orbit it, stop at any side, tap a unit and see its floor, size, orientation and plan — the view and the numbers in one place.",
    introDe: "Bei einer Überbauung mit vierzig Wohnungen lautet die Frage nicht «ist es schön», sondern «welche ist meine». Der Navigator ist das Gebäude, das man in den Händen dreht: umkreisen, an jeder Seite anhalten, eine Wohnung antippen und Geschoss, Fläche, Ausrichtung und Grundriss sehen — Aussicht und Zahlen an einem Ort.",
    problems: [
      { problem: "The unit list is a spreadsheet", problemDe: "Der Wohnungsspiegel ist eine Tabelle", title: "Pick the apartment on the building", titleDe: "Die Wohnung am Gebäude auswählen", desc: "Every unit is a clickable volume on the rendered building. Status (available, reserved, sold), price, area and floor plan appear on tap; filters narrow the building to '3.5 rooms, south-facing, above the third floor'.", descDe: "Jede Wohnung ist ein anklickbares Volumen am gerenderten Gebäude. Status (frei, reserviert, verkauft), Preis, Fläche und Grundriss erscheinen beim Antippen; Filter reduzieren das Gebäude auf «3,5 Zimmer, Südlage, über dem dritten Stock»." },
      { problem: "Buyers want to see their side of the building", problemDe: "Käufer wollen ihre Seite des Gebäudes sehen", title: "360° around the ensemble", titleDe: "360° um das Ensemble", desc: "The orbit is rendered as a sequence of frames from the full context model, so the buyer turns the real building in its real surroundings — the courtyard, the street, the view each facade gets.", descDe: "Die Umrundung wird als Bildsequenz aus dem vollständigen Umgebungsmodell gerendert, der Käufer dreht also das echte Gebäude in seiner echten Umgebung — Hof, Strasse, die Aussicht jeder Fassade." },
      { problem: "Sales data changes every week", problemDe: "Verkaufsdaten ändern sich jede Woche", title: "Live status from your list", titleDe: "Live-Status aus Ihrer Liste", desc: "The navigator reads a spreadsheet or your CRM: mark a unit sold in the list and it greys out on the building within minutes. No developer needed for the daily updates.", descDe: "Der Navigator liest eine Tabelle oder Ihr CRM: Markieren Sie eine Wohnung in der Liste als verkauft, wird sie innerhalb von Minuten am Gebäude grau. Für die täglichen Updates braucht es keinen Entwickler." }
    ],
    deliverables: ["Interactive 360° orbit of the building with clickable units", "Unit data, status and floor plans from your spreadsheet or CRM", "Filters by rooms, floor, orientation, price and status", "Embed for your project website, phone and desktop", "Hosting and status updates for the sales period"],
    deliverablesDe: ["Interaktive 360°-Umrundung des Gebäudes mit anklickbaren Wohnungen", "Wohnungsdaten, Status und Grundrisse aus Ihrer Tabelle oder Ihrem CRM", "Filter nach Zimmern, Geschoss, Ausrichtung, Preis und Status", "Einbettung für Ihre Projektwebsite, Smartphone und Desktop", "Hosting und Statusupdates für die Verkaufsphase"],
    investment: { from: 6900, unit: "per building", unitDe: "pro Gebäude", includes: ["Orbit rendering from the context model", "Unit mapping and data connection", "Filters and unit detail panel", "Hosting for 24 months"], includesDe: ["Rendering der Umrundung aus dem Umgebungsmodell", "Wohnungszuordnung und Datenanbindung", "Filter und Wohnungsdetail", "Hosting für 24 Monate"], turnaround: "4–6 weeks; 3 weeks when the exterior model already exists", turnaroundDe: "4–6 Wochen; 3 Wochen, wenn das Aussenmodell bereits besteht", revisions: 2 },
    faq: [
      { q: "How many apartments can the 360° navigator handle?", qDe: "Wie viele Wohnungen schafft der 360°-Navigator?", a: "From a single building with eight units to a quarter with several hundred. For larger ensembles the navigator starts at the site level and zooms into each building.", aDe: "Von einem einzelnen Gebäude mit acht Wohnungen bis zu einem Quartier mit mehreren hundert. Bei grösseren Ensembles beginnt der Navigator auf Arealebene und zoomt in jedes Gebäude." },
      { q: "Where does the navigator's unit data come from?", qDe: "Woher kommen die Wohnungsdaten des Navigators?", a: "From a shared spreadsheet, your CRM or a simple admin page we provide. You change a status or a price there and the navigator updates itself within minutes.", aDe: "Aus einer geteilten Tabelle, Ihrem CRM oder einer einfachen Admin-Seite, die wir bereitstellen. Sie ändern dort einen Status oder einen Preis, und der Navigator aktualisiert sich innerhalb von Minuten." },
      { q: "Does the apartment navigator work on phones?", qDe: "Funktioniert der Wohnungsnavigator auf dem Smartphone?", a: "Yes. The orbit is a pre-rendered frame sequence, so it runs smoothly on any phone without a 3D engine, and the unit panel is designed for touch.", aDe: "Ja. Die Umrundung ist eine vorgerenderte Bildsequenz, sie läuft also auf jedem Smartphone flüssig ohne 3D-Engine, und das Wohnungspanel ist für Touch gestaltet." },
      { q: "How much does a 360° apartment navigator cost?", qDe: "Was kostet ein 360°-Wohnungsnavigator?", a: "From CHF 6,900 for one building when the exterior model exists from our renderings; from CHF 9,900 built from scratch. Several buildings on one site are quoted together, with the context work shared.", aDe: "Ab CHF 6'900 für ein Gebäude, wenn das Aussenmodell aus unseren Renderings besteht; ab CHF 9'900 von Grund auf. Mehrere Gebäude auf einem Areal werden gemeinsam offeriert, die Kontextarbeit wird geteilt." },
      { q: "Can the navigator be combined with the 360° tour and 3D floor plans?", qDe: "Lässt sich der Navigator mit 360°-Rundgang und 3D-Grundrissen kombinieren?", a: "That is the intended setup: tap a unit on the building, see its 3D floor plan, open its tour. All three come from the same model, which is why ordering them together is the economical route.", aDe: "Genau dafür ist er gedacht: Wohnung am Gebäude antippen, ihren 3D-Grundriss sehen, ihren Rundgang öffnen. Alle drei stammen aus demselben Modell — deshalb ist die gemeinsame Bestellung der günstige Weg." },
      { q: "Who hosts the navigator and for how long?", qDe: "Wer hostet den Navigator und wie lange?", a: "We host it for 24 months, included. Afterwards, CHF 50 per month or a handover of the files to your own hosting.", aDe: "Wir hosten ihn 24 Monate lang, inbegriffen. Danach CHF 50 pro Monat oder eine Übergabe der Dateien auf Ihr eigenes Hosting." }
    ]
  },

  "web-development": {
    investment: { from: 7900, unit: "per project site", unitDe: "pro Projektwebsite", includes: ["Design and build, desktop and mobile", "Renders, tours and films integrated", "Unit table, floor plans and enquiry form", "German and English, hosting and analytics"], includesDe: ["Gestaltung und Umsetzung, Desktop und Mobile", "Renderings, Rundgänge und Filme eingebunden", "Wohnungsspiegel, Grundrisse und Anfrageformular", "Deutsch und Englisch, Hosting und Analytics"], turnaround: "4–6 weeks from briefing to launch", turnaroundDe: "4–6 Wochen vom Briefing bis zum Launch", revisions: 2 },
    faq: [
      { q: "How much does a real estate project website cost?", qDe: "Was kostet eine Immobilien-Projektwebsite?", a: "From CHF 7,900 for a development site with unit table, floor plans, gallery, tour embed and enquiry form in two languages. A single-property landing page is from CHF 3,900; a studio portfolio from CHF 5,900. Fixed price after the briefing.", aDe: "Ab CHF 7'900 für eine Projektwebsite mit Wohnungsspiegel, Grundrissen, Galerie, eingebettetem Rundgang und Anfrageformular in zwei Sprachen. Eine Landingpage für ein einzelnes Objekt ab CHF 3'900; ein Büroportfolio ab CHF 5'900. Fixpreis nach dem Briefing." },
      { q: "How long does a project website take to build?", qDe: "Wie lange dauert die Umsetzung einer Projektwebsite?", a: "Four to six weeks from briefing to launch: structure in week one, design in weeks two and three, build and content in weeks four and five, testing and launch in week six. Faster when the renderings and texts are ready at the start.", aDe: "Vier bis sechs Wochen vom Briefing bis zum Launch: Struktur in Woche eins, Design in Woche zwei und drei, Umsetzung und Inhalte in Woche vier und fünf, Test und Launch in Woche sechs. Schneller, wenn Renderings und Texte zu Beginn bereitliegen." },
      { q: "Can we update the project website ourselves?", qDe: "Können wir die Projektwebsite selbst pflegen?", a: "Yes. Unit status, prices and texts are edited in a simple admin or a spreadsheet; no developer needed for the weekly changes. We also offer maintenance for the sales period if you prefer not to.", aDe: "Ja. Wohnungsstatus, Preise und Texte werden in einer einfachen Admin-Oberfläche oder einer Tabelle gepflegt; für die wöchentlichen Änderungen braucht es keinen Entwickler. Auf Wunsch übernehmen wir die Betreuung für die Verkaufsphase." },
      { q: "Who owns the project website and the domain?", qDe: "Wem gehören Projektwebsite und Domain?", a: "You do. The domain is registered in your name, the code and the content are handed over at launch, and the hosting account is yours. Nothing is locked to us.", aDe: "Ihnen. Die Domain wird auf Ihren Namen registriert, Code und Inhalte werden beim Launch übergeben, und das Hosting-Konto gehört Ihnen. Nichts ist an uns gebunden." },
      { q: "Will the project website be found on Google?", qDe: "Wird die Projektwebsite auf Google gefunden?", a: "The site launches with the technical basis in place: fast loading, both languages, structured data, sitemap, Search Console. It will rank for the project name within days. Ranking for generic terms like 'apartment Winterthur' depends on content and time, and we advise on that.", aDe: "Die Website startet mit der technischen Basis: schnelles Laden, beide Sprachen, strukturierte Daten, Sitemap, Search Console. Für den Projektnamen rankt sie innerhalb von Tagen. Ein Ranking für generische Begriffe wie «Wohnung Winterthur» hängt von Inhalt und Zeit ab, und dazu beraten wir." },
      { q: "What happens to the project website after the development sells out?", qDe: "Was passiert mit der Projektwebsite, wenn das Projekt ausverkauft ist?", a: "The site can switch to a 'sold out' page that keeps the renders and points to your next project, or be archived. Hosting is a few francs a month, so most clients keep it as a reference.", aDe: "Die Website kann auf eine «Ausverkauft»-Seite umschalten, die die Renderings behält und auf Ihr nächstes Projekt verweist, oder archiviert werden. Das Hosting kostet wenige Franken im Monat, die meisten Kunden behalten sie als Referenz." }
    ]
  }
};

// Flattens the De siblings to the requested language, same rule as
// localizeService: anything without a German string falls back to English.
function localizeServiceContentBase(slug, locale) {
  const c = serviceContent[slug];
  if (!c) return {};
  const de = locale === "de";
  const pick = (en, deVal) => (de && deVal ? deVal : en);
  const out = {};
  if (c.intro) out.intro = pick(c.intro, c.introDe);
  if (c.problems) {
    out.problems = c.problems.map((p) => ({
      problem: pick(p.problem, p.problemDe),
      title: pick(p.title, p.titleDe),
      desc: pick(p.desc, p.descDe),
    }));
  }
  if (c.deliverables) out.deliverables = pick(c.deliverables, c.deliverablesDe);
  if (c.investment) {
    const i = c.investment;
    out.investment = {
      from: i.from,
      currency: PRICE_CURRENCY,
      unit: pick(i.unit, i.unitDe),
      includes: pick(i.includes, i.includesDe),
      turnaround: pick(i.turnaround, i.turnaroundDe),
      revisions: i.revisions,
    };
  }
  if (c.faq) out.faq = c.faq.map((f) => ({ q: pick(f.q, f.qDe), a: pick(f.a, f.aDe) }));
  return out;
}

// Swiss number formatting for prices: CHF 4'900.
export function formatPrice(amount, currency = PRICE_CURRENCY) {
  return `${currency} ${amount.toLocaleString("de-CH").replace(/’|’|'/g, "'")}`;
}

export function localizeServiceContent(slug, locale) {
  return locale === "es" ? mergeOverlay(localizeServiceContentBase(slug, "en"), esOverlay[slug]) : localizeServiceContentBase(slug, locale);
}
